const textoLLM = $input.all()[0].json.text;
try {
  const datos = JSON.parse(textoLLM);
  return [{ json: { exito: true, datos_extraidos: datos, texto_original: $('Webhook - Recibe Texto').item.json.body.texto } }];
} catch (e) {
  return [{ json: { exito: false, error: 'El LLM no devolvió JSON válido', respuesta_cruda: textoLLM } }];
}
